import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"独立重比对工具","description":"","frontmatter":{"title":"独立重比对工具","order":7},"headers":[],"relativePath":"realignment/standalone.md","filePath":"realignment/standalone.md"}'),l={name:"realignment/standalone.md"};function n(o,e,s,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="独立重比对工具" tabindex="-1">独立重比对工具 <a class="header-anchor" href="#独立重比对工具" aria-label="Permalink to &quot;独立重比对工具&quot;">​</a></h1><h2 id="vertical" tabindex="-1">纵向分割方法 <a class="header-anchor" href="#vertical" aria-label="Permalink to &quot;纵向分割方法 {#vertical}&quot;">​</a></h2><p>Cut the input sequences into substrings, and once these shorter substrings are realigned, they stitch their alignments together.</p><h3 id="_1-refin-align-2019" tabindex="-1"><a href="https://informatica.si/index.php/informatica/article/view/2621/0" target="_blank" rel="noreferrer">1. Refin-Align (2019)</a> <a class="header-anchor" href="#_1-refin-align-2019" aria-label="Permalink to &quot;[1. Refin-Align (2019)](https://informatica.si/index.php/informatica/article/view/2621/0)&quot;">​</a></h3><p>In each iteration:</p><ol><li>Extract the blocks from the initial alignment based on the columns with the same bases.</li><li>Delete all gaps in each block and realign it with Promalign.</li><li>Calculate the SP score of the initial block and the new block.</li><li>If the score of the new one is higher than the initial, the new block will be the input of the next iteration.</li></ol><p>Until no longer improve the SP score of each block.</p><ul><li>Test data: Protein (BALIBASE, PREFAB, OXBENCH, HOMSTRAD)</li><li>The source code is not publicized.</li></ul><h3 id="_2-splivert-2020" tabindex="-1"><a href="https://www.ingentaconnect.com/content/ben/ppl/2020/00000027/00000004/art00007" target="_blank" rel="noreferrer">2. SpliVert (2020)</a> <a class="header-anchor" href="#_2-splivert-2020" aria-label="Permalink to &quot;[2. SpliVert (2020)](https://www.ingentaconnect.com/content/ben/ppl/2020/00000027/00000004/art00007)&quot;">​</a></h3><ol><li>Split the initial alignment vertically into 3 parts.</li><li>Remove the gap characters in the middle part and realign it alone.</li><li>Splice the realigned middle parts with the other two initial pieces to obtain a realigned alignment.</li></ol><ul><li>Test data: Protein (BALIBASE, OXBENCH, SABmark)</li><li>We did not find the source code.</li></ul><h3 id="_3-rpfam-2022" tabindex="-1"><a href="https://www.worldscientific.com/doi/epdf/10.1142/S0219720022400029" target="_blank" rel="noreferrer">3. RPfam (2022)</a> <a class="header-anchor" href="#_3-rpfam-2022" aria-label="Permalink to &quot;[3. RPfam (2022)](https://www.worldscientific.com/doi/epdf/10.1142/S0219720022400029)&quot;">​</a></h3><p>RPfam employs the Simulated Annealing algorithm in iteration.</p><p>In each iteration:</p><ol><li>Scan the current MSA for badly aligned blocks and compute score of the blocks.</li><li>Randomly pick a badly aligned block.</li><li>Seek the worst aligned fragment in the block.</li><li>Realign the fragment utilizing DP algorithm.</li><li>Update the current MSA.</li></ol><p>Until the temperature is down to the setting value the iteration ends.</p><ul><li>Test data: Protein (PFAM)</li><li>The source code is not publicized.</li></ul><h2 id="horizontal" tabindex="-1">横向分割方法 <a class="header-anchor" href="#horizontal" aria-label="Permalink to &quot;横向分割方法 {#horizontal}&quot;">​</a></h2><p>Split an alignment into groups of whole sequences, which are then merged together by realigning between groups, possibly using each group’s induced subalignment.</p><h3 id="_1-realigner-1997" tabindex="-1"><a href="https://dl.acm.org/doi/pdf/10.1145/267521.267524" target="_blank" rel="noreferrer">1. ReAligner (1997)</a> <a class="header-anchor" href="#_1-realigner-1997" aria-label="Permalink to &quot;[1. ReAligner (1997)](https://dl.acm.org/doi/pdf/10.1145/267521.267524)&quot;">​</a></h3><p>In each iteration has a traversal of all sequence:</p><ol><li>Pick a sequence</li><li>Realign the sequence with the profile constructed with the remaining sequences.</li><li>If the new alignment&#39;s quality is improved, the new one will replace the old one.</li></ol><p>Until the alignment score saturates to a stable value.</p><ul><li>Test data: DNA/RNA</li><li><a href="ftp://ftp.cs.arizona.edu/realigner" target="_blank" rel="noreferrer">The source code link is unavailable.</a></li></ul><h3 id="_2-remove-first-method-2005" tabindex="-1"><a href="https://academic.oup.com/bioinformatics/article/21/8/1408/249176" target="_blank" rel="noreferrer">2. Remove First method (2005)</a> <a class="header-anchor" href="#_2-remove-first-method-2005" aria-label="Permalink to &quot;[2. Remove First method (2005)](https://academic.oup.com/bioinformatics/article/21/8/1408/249176)&quot;">​</a></h3><p>In each iteration:</p><ol><li>Randomly pick a sequence.</li><li>Realign the sequence with the profile constructed with the remaining sequences.</li><li>Update the alignment if the accuracy improved.</li></ol><p>Until the score converges or the reach the limit of iterations.</p><ul><li>Test data: Protein (HOMSTRAD)</li><li><a href="http://www.bioinf.ucd.ie/people/iain/iteration.html" target="_blank" rel="noreferrer">Source code</a></li></ul><h3 id="_3-treerefiner-2005" tabindex="-1"><a href="https://ieeexplore.ieee.org/abstract/document/1498013" target="_blank" rel="noreferrer">3. TreeRefiner (2005)</a> <a class="header-anchor" href="#_3-treerefiner-2005" aria-label="Permalink to &quot;[3. TreeRefiner (2005)](https://ieeexplore.ieee.org/abstract/document/1498013)&quot;">​</a></h3><p>This realigner is based on three-dimensional alignment rather than using an iterative approach.</p><ul><li>Test data: Nucleotide sequences that were generated by the Rose program</li><li><a href="http://treerefiner.stanford.edu/index.html" target="_blank" rel="noreferrer">TreeRefiner&#39;s homepage</a></li></ul><h3 id="_4-refiner-2006" tabindex="-1"><a href="https://academic.oup.com/nar/article/34/9/2598/2401672" target="_blank" rel="noreferrer">4. REFINER (2006)</a> <a class="header-anchor" href="#_4-refiner-2006" aria-label="Permalink to &quot;[4. REFINER (2006)](https://academic.oup.com/nar/article/34/9/2598/2401672)&quot;">​</a></h3><p>This realigner is similar to RF method but aims to realign the sequences with the family block models representing conserved sequence/structure regions.</p><p>In each iteration:</p><ol><li>Randomly pick a sequence.</li><li>Realign the sequence with the PSSM constructed with the remaining sequences.</li><li>Update the alignment.</li></ol><p>Until the alignment score saturates to a stable value or until the iteration cycle terminates.</p><ul><li>Test data: Protein (<a href="http://www.ncbi.nlm.nih.gov/Structure/cdd/cdd.shtml" target="_blank" rel="noreferrer">CDD</a> and PFAM)</li><li><a href="ftp://ftp.ncbi.nih.gov/pub/REFINER" target="_blank" rel="noreferrer">FTP server</a></li></ul><h3 id="_5-reformalign-2014" tabindex="-1"><a href="https://link.springer.com/article/10.1186/1471-2105-15-265" target="_blank" rel="noreferrer">5. ReformAlign (2014)</a> <a class="header-anchor" href="#_5-reformalign-2014" aria-label="Permalink to &quot;[5. ReformAlign (2014)](https://link.springer.com/article/10.1186/1471-2105-15-265)&quot;">​</a></h3><p>In each iteration:</p><ol><li>Build a profile from the initial alignment.</li><li>All sequences realign with the profile to obtain the reformed alignment. (There has a profile fine-tuning model.)</li><li>The alignment with better quality will be the input of next iteration.</li></ol><p>Until the alignment between two successive runs remains unchanged or a predefined maximum number of iterations is reached.</p><ul><li>Test data: DNA/RNA (BRAliBase 2.1 RNA alignment database and DNA SMART database)</li><li><a href="http://evol.bio.lmu.de/_statgen/software/reformalign/" target="_blank" rel="noreferrer">ReformAlign&#39;s homepage</a></li></ul><h2 id="combined" tabindex="-1">横纵组合方法 <a class="header-anchor" href="#combined" aria-label="Permalink to &quot;横纵组合方法 {#combined}&quot;">​</a></h2><h3 id="_1-rascal-2003" tabindex="-1"><a href="https://academic.oup.com/bioinformatics/article-abstract/19/9/1155/285019" target="_blank" rel="noreferrer">1. RASCAL (2003)</a> <a class="header-anchor" href="#_1-rascal-2003" aria-label="Permalink to &quot;[1. RASCAL (2003)](https://academic.oup.com/bioinformatics/article-abstract/19/9/1155/285019)&quot;">​</a></h3><p>The alignment is initially divided <strong>horizontally and vertically</strong> to identify well-aligned, reliable regions. Potential alignment errors are detected by comparing statistical models of the reliable regions. RASCAL then performs a single realignment of each badly aligned region using an algorithm similar to that implemented in ClustalW.</p><p>Partitioning steps:</p><ol><li>The alignment is divided horizontally into sequence subfamilies using Secator</li><li>Then the alignment is divided vertically into &#39;core block&#39; regions that are reliably aligned in the majority of the sequences.</li></ol><p>These global core blocks are determined using the mean distance column scores implemented in the NorMD OF. Local core block regions are also determined for each subfamily individually, using the same method as for the complete family.</p><ul><li>Test data: Protein (BALIBASE, ProDom)</li><li><a href="ftp://ftp-igbmc.u-strasbg.fr/pub/RASCAL" target="_blank" rel="noreferrer">The source code link is unavailable.</a></li></ul><h3 id="_2-crumble-and-prune-2011" tabindex="-1"><a href="https://bmcbioinformatics.biomedcentral.com/articles/10.1186/1471-2105-12-144#Sec3" target="_blank" rel="noreferrer">2. Crumble and Prune (2011)</a> <a class="header-anchor" href="#_2-crumble-and-prune-2011" aria-label="Permalink to &quot;[2. Crumble and Prune (2011)](https://bmcbioinformatics.biomedcentral.com/articles/10.1186/1471-2105-12-144#Sec3)&quot;">​</a></h3><p>[vertical] <strong>Crumble</strong> deals with problems that are large in sequence length. It breaks up long alignment problems into shorter problems.</p><p>[horizontal] <strong>Prune</strong> handles problems with a large number of sequences. It cuts up deep alignment problems into sub-problems with fewer sequences.</p><p><strong>Job-tree</strong> combine Crumble and Prune to align long and deep sequences.</p><ul><li>Test data: human genome, Rfam</li><li><a href="http://hgwdev.cse.ucsc.edu/~krish/crumble_prune/" target="_blank" rel="noreferrer">The source code link is unavailable.</a></li></ul>',55)])])}const u=a(l,[["render",n]]);export{p as __pageData,u as default};
